package com.collectioncelebrations;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.client.config.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
public class ConfigVisibilityTest
{
	@Test
	public void everySettingsItemHasAVisibleSection()
	{
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		ConfigDescriptor descriptor = manager.getConfigDescriptor(new CelebrationConfig() {});
		Set<String> sections = descriptor.getSections().stream().map(ConfigSectionDescriptor::getKey).collect(Collectors.toSet());
		assertTrue(sections.contains("valueDrops"));
		assertTrue(sections.contains("clueDrops"));
		assertFalse(sections.contains("specWeapon"));
		assertEquals(6, sections.size());
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			assertTrue(item.getItem().keyName(), item.getItem().section().isEmpty() || sections.contains(item.getItem().section()));
		}
		assertTrue(descriptor.getItems().size() > 60);
	}
	@Test
	public void settingsInOneSectionNeverShareAPosition()
	{
		// Shared positions fall back to alphabetical order, which split the Pet settings in two.
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		Set<String> seen = new java.util.HashSet<>();
		for (ConfigItemDescriptor item : manager.getConfigDescriptor(new CelebrationConfig() {}).getItems())
		{
			String slot = item.getItem().section() + " #" + item.getItem().position();
			assertTrue(item.getItem().keyName() + " shares " + slot, item.getItem().hidden() || seen.add(slot));
		}
	}
	@Test
	public void oldTextModesCarryOverOnlyTheirOutline()
	{
		for (String[] modes : new String[][] {{"SMOOTH_OUTLINED", "SHADOW"}, {"SMOOTH", "NONE"}, {"CRISP", "NONE"}})
		{
			ConfigManager manager = mock(ConfigManager.class);
			when(manager.getConfiguration("collection-celebrations", "textRenderMode")).thenReturn(modes[0]);
			CelebrationPlugin.migrateTextOutline(manager);
			verify(manager).setConfiguration("collection-celebrations", "textOutline", TextOutline.valueOf(modes[1]));
			verify(manager).unsetConfiguration("collection-celebrations", "textRenderMode");
		}
		// A choice already made in the new setting stays, and without the old setting nothing happens at all.
		ConfigManager chosen = mock(ConfigManager.class);
		when(chosen.getConfiguration("collection-celebrations", "textRenderMode")).thenReturn("CRISP");
		when(chosen.getConfiguration("collection-celebrations", "textOutline")).thenReturn("OUTLINE");
		CelebrationPlugin.migrateTextOutline(chosen);
		verify(chosen, never()).setConfiguration(anyString(), anyString(), any(Object.class));
		verify(chosen).unsetConfiguration("collection-celebrations", "textRenderMode");
		ConfigManager fresh = mock(ConfigManager.class);
		CelebrationPlugin.migrateTextOutline(fresh);
		verify(fresh, never()).unsetConfiguration(anyString(), anyString());
	}
	@Test
	public void wikiNetworkAccessIsOptOutWithPrivacyWarning()
	{
		CelebrationConfig config = new CelebrationConfig() {};
		// On by default, so the popup has rates out of the box; the switch remains the way to stop it.
		assertTrue(config.refreshWikiData());
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		ConfigItem item = manager.getConfigDescriptor(config).getItems().stream()
			.map(ConfigItemDescriptor::getItem).filter(c -> c.keyName().equals("refreshWikiData"))
			.findFirst().orElseThrow();
		assertEquals("This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers", item.warning());
	}

}

package com.collectioncelebrations;

import net.runelite.client.plugins.grounditems.GroundItemsConfig;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GroundItemSoundFilterTest
{
	private final GroundItemsConfig config = mock(GroundItemsConfig.class, CALLS_REAL_METHODS);
	private boolean hidden(String name, int quantity, int ge, int ha, boolean tradeable)
	{
		return GroundItemSoundFilter.hidden(config, name, quantity, ge, ha, tradeable);
	}

	@Test
	public void namesWildcardsQuantityAndLiveChanges()
	{
		when(config.getHiddenItems()).thenReturn("Rune *, Coins < 100, Bones");
		assertTrue(hidden("rune sword", 1, 100000, 10000, true));
		assertTrue(hidden("COINS", 99, 99, 99, true));
		assertFalse(hidden("Coins", 100, 100, 100, true));
		assertTrue(hidden("bones", 1, 100, 100, true));
		when(config.getHiddenItems()).thenReturn("");
		assertFalse(hidden("bones", 1, 100, 100, true));
	}
	@Test
	public void exactRulesWinAndHighlightsBreakTies()
	{
		when(config.getHiddenItems()).thenReturn("Rune sword");
		when(config.getHighlightItems()).thenReturn("Rune *");
		assertTrue(hidden("Rune sword", 1, 100, 100, true));
		when(config.getHighlightItems()).thenReturn("Rune sword");
		assertFalse(hidden("Rune sword", 1, 100, 100, true));
		when(config.getHiddenItems()).thenReturn("Rune *");
		assertFalse(hidden("Rune sword", 1, 100, 100, true));
	}
	@Test
	public void thresholdRequiresBothPricesAndHonoursUntradeables()
	{
		when(config.getHideUnderValue()).thenReturn(100);
		assertTrue(hidden("Test", 1, 99, 99, true));
		assertFalse(hidden("Test", 1, 100, 99, true));
		assertFalse(hidden("Test", 1, 99, 100, true));
		assertFalse(hidden("Test", 1, 0, 0, false));
		when(config.dontHideUntradeables()).thenReturn(false);
		assertTrue(hidden("Test", 1, 0, 0, false));
		when(config.getHighlightItems()).thenReturn("Test");
		assertFalse(hidden("Test", 1, 0, 0, false));
	}
}

package com.collectioncelebrations;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.grounditems.GroundItemsConfig;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CombinationValueFloorTest
{
	private ItemManager items;
	private CelebrationConfig config;
	private RarityResolver resolver;
	private Map<String, RarityResolver.CompletionEntry> data;
	private ItemComposition target;

	@Before
	public void setup()
	{
		items = mock(ItemManager.class);
		config = mock(CelebrationConfig.class, CALLS_REAL_METHODS);
		ItemComposition tradeable = mock(ItemComposition.class);
		when(tradeable.isGeTradeable()).thenReturn(true);
		when(items.getItemComposition(anyInt())).thenReturn(tradeable);
		target = mock(ItemComposition.class);
		when(target.isGeTradeable()).thenReturn(true);
		when(items.getItemComposition(1)).thenReturn(target);
		when(items.getItemPrice(anyInt())).thenReturn(100_000_000L);
		data = new HashMap<>();
		for (int id = 1; id <= 100; id++)
		{
			RarityResolver.CompletionEntry entry = new RarityResolver.CompletionEntry();
			entry.name = id == 1 ? "Tormented synapse" : "Example " + id;
			entry.comp = id == 1 ? 100.0 : 0.0;
			entry.tabs = List.of();
			data.put(String.valueOf(id), entry);
		}
		resolver = new RarityResolver(items, config, new DropRateResolver());
		resolver.groundItemsConfig = mock(GroundItemsConfig.class);
		when(resolver.groundItemsConfig.mediumValuePrice()).thenReturn(100_000);
		when(resolver.groundItemsConfig.highValuePrice()).thenReturn(1_000_000);
		when(resolver.groundItemsConfig.insaneValuePrice()).thenReturn(10_000_000);
		resolver.reload(data);
	}

	private RarityTier tier(int price)
	{
		when(items.getItemPrice(1)).thenReturn((long) price);
		return resolver.resolve(1, "Tormented synapse").getTier();
	}

	@Test
	public void expensiveSynapseCannotBeDemotedByHighCompletion()
	{
		assertTrue(config.groundItemThresholds());
		assertEquals(RarityBasis.COMBINATION, config.rarityBasis());
		assertEquals(RarityTier.VERY_RARE, tier(38_000_000));
		assertEquals(RarityTier.VERY_RARE, tier(40_000_000));
	}

	@Test
	public void floorFollowsGroundItemsBoundariesAndEdits()
	{
		assertEquals(RarityTier.COMMON, tier(99_999));
		assertEquals(RarityTier.UNCOMMON, tier(100_000));
		assertEquals(RarityTier.UNCOMMON, tier(999_999));
		assertEquals(RarityTier.RARE, tier(1_000_000));
		assertEquals(RarityTier.RARE, tier(9_999_999));
		assertEquals(RarityTier.VERY_RARE, tier(10_000_000));
		when(resolver.groundItemsConfig.insaneValuePrice()).thenReturn(50_000_000);
		assertEquals(RarityTier.RARE, tier(40_000_000));
	}

	@Test
	public void explicitUnlinkedCutoffsRemainUsable()
	{
		when(config.groundItemThresholds()).thenReturn(false);
		when(config.veryRareAt()).thenReturn(50_000_000);
		assertEquals(RarityTier.RARE, tier(40_000_000));
		assertEquals(RarityTier.VERY_RARE, tier(50_000_000));
	}

	@Test
	public void wikiCanStillPromoteCheapItems()
	{
		when(items.getItemPrice(anyInt())).thenReturn(1000L);
		data.values().forEach(entry -> entry.comp = 100.0);
		data.get("1").comp = 0.1;
		resolver.reload(data);
		assertEquals(RarityTier.VERY_RARE, tier(1000));
	}

	@Test
	public void wikiOnlyUntradeablesAndPetsKeepTheirOwnRules()
	{
		when(config.rarityBasis()).thenReturn(RarityBasis.RARITY);
		assertEquals(RarityTier.COMMON, tier(40_000_000));
		when(config.rarityBasis()).thenReturn(RarityBasis.COMBINATION);
		when(target.isGeTradeable()).thenReturn(false);
		assertEquals(RarityTier.COMMON, tier(40_000_000));
		data.get("1").tabs = List.of("All Pets");
		resolver.reload(data);
		assertEquals(RarityTier.PET, tier(40_000_000));
	}
}

package com.collectioncelebrations;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyMap;
import static org.mockito.Mockito.*;

public class WikiLifecycleTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private static java.nio.file.Path path(net.runelite.client.util.Filepath folder)
	{
		return net.runelite.client.util.Filepath.Unchecked.getPath(folder);
	}

	private WikiRarity create() throws Exception
	{
		WikiRarity wiki = new WikiRarity();
		wiki.dataDirectory = net.runelite.client.util.Filepath.Unchecked.getRooted(folder.newFolder().toPath());
		wiki.gson = new Gson();
		wiki.config = mock(CelebrationConfig.class, CALLS_REAL_METHODS);
		wiki.remote = new WikiCompletionClient();
		wiki.remote.gson = wiki.gson;
		wiki.resolver = mock(RarityResolver.class);
		wiki.dropRates = new DropRateResolver();
		return wiki;
	}

	/** Only the first page carries rows; the empty page after it is what ends the paging loop. */
	private static String bucket(okhttp3.Request request, com.google.gson.JsonObject... rows)
	{
		String query = request.url().queryParameter("query");
		if (query == null || !query.contains(".offset(0)."))
		{
			return "{\"bucket\":[]}";
		}
		StringBuilder body = new StringBuilder("{\"bucket\":[");
		for (int i = 0; i < rows.length; i++)
		{
			body.append(i > 0 ? "," : "").append(rows[i]);
		}
		return body.append("]}").toString();
	}

	private okhttp3.Response response(okhttp3.Interceptor.Chain chain)
	{
		String body = chain.request().url().encodedPath().endsWith("data.json") ? "[{\"id\":1,\"name\":\"Example\"}]" : "{\"1\":50}";
		if (chain.request().url().encodedPath().equals("/api.php"))
		{
			body = bucket(chain.request(), WikiDropRatesTest.row("Boss", "Example", "1/512"));
		}
		return new okhttp3.Response.Builder()
			.request(chain.request())
			.protocol(okhttp3.Protocol.HTTP_1_1)
			.code(200)
			.message("OK")
			.body(okhttp3.ResponseBody.create(okhttp3.MediaType.parse("application/json"), body))
			.build();
	}

	private void awaitCache(WikiRarity wiki) throws Exception
	{
		java.nio.file.Path cache = path(wiki.dataDirectory).resolve("wiki-drop-rates-cache.json");
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (!java.nio.file.Files.exists(cache) && System.nanoTime() < deadline) { Thread.sleep(10); }
		assertTrue("Drop-rate cache was not written", java.nio.file.Files.exists(cache));
	}

	private static long at(String instant)
	{
		return java.time.Instant.parse(instant).toEpochMilli();
	}

	@Test
	public void aCacheGoesStaleOnTheThursdayAfterTheGameUpdate()
	{
		// 2026-09-17 is a Thursday, 09-16 the Wednesday update before it, 09-24 the Thursday after.
		long friday = at("2026-09-18T12:00:00Z");
		assertFalse("Fetched that Thursday, still current on Friday", WikiRarity.staleSince(at("2026-09-17T09:00:00Z"), friday));
		assertTrue("Fetched before the Thursday cutoff", WikiRarity.staleSince(at("2026-09-16T23:59:59Z"), friday));
		// Anything from the previous week is stale once the next Thursday starts.
		assertFalse(WikiRarity.staleSince(at("2026-09-18T12:00:00Z"), at("2026-09-23T23:59:59Z")));
		assertTrue(WikiRarity.staleSince(at("2026-09-18T12:00:00Z"), at("2026-09-24T00:00:00Z")));
		// A cache is never kept for longer than a week, and a broken timestamp always refreshes.
		assertTrue(WikiRarity.staleSince(at("2026-09-17T00:00:00Z"), at("2026-09-24T00:00:00Z")));
		assertTrue(WikiRarity.staleSince(0, friday));
		assertTrue("A timestamp from the future cannot be trusted", WikiRarity.staleSince(at("2027-01-01T00:00:00Z"), friday));
	}

	@Test
	public void aCacheFromAnOlderFormatIsReplacedEvenWhenItIsFresh() throws Exception
	{
		WikiRarity wiki = create();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(this::response).build();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		java.nio.file.Files.createDirectories(path(wiki.dataDirectory));
		java.nio.file.Path cache = path(wiki.dataDirectory).resolve("wiki-drop-rates-cache.json");
		// Written today, but by a build whose rates were formatted differently.
		java.nio.file.Files.writeString(cache, "{\"fetchedAt\":" + System.currentTimeMillis()
			+ ",\"rates\":{\"Boss\":{\"Example\":\"1/9,999\"}}}");
		try
		{
			wiki.start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (!"1/512".equals(wiki.dropRateText("Boss", "Example")) && System.nanoTime() < deadline) { Thread.sleep(10); }
			assertEquals("A formatless cache must be refetched, not displayed", "1/512", wiki.dropRateText("Boss", "Example"));
			assertTrue(java.nio.file.Files.readString(cache).contains("\"format\""));
		}
		finally { wiki.stop(); }
	}

	@Test
	public void localRatesStillResolveByNameWhileWikiTablesAreAbsent() throws Exception
	{
		WikiRarity wiki = create();
		wiki.dropRates.reload(java.util.Map.of("Boss variant",
			java.util.Map.of("Example", 0.002, "Rare example", 0.00005)));
		// Nothing downloaded yet, so the local dataset is the only source and must not be withheld.
		assertEquals("1/500", wiki.dropRateText("Some other boss", "Example"));
		assertEquals("1/500", wiki.dropRateText(null, "Example"));
		// Local rates follow the same separator threshold as the downloaded ones.
		assertEquals("1/20,000", wiki.dropRateText(null, "Rare example"));
	}

	@Test
	public void flickingTheSwitchCannotRepeatAFullDownload() throws Exception
	{
		WikiRarity wiki = create();
		java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain -> {
			calls.incrementAndGet();
			return response(chain);
		}).build();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		try
		{
			wiki.start();
			awaitCache(wiki);
			int afterStart = calls.get();
			wiki.refreshSetting();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (calls.get() == afterStart && System.nanoTime() < deadline) { Thread.sleep(10); }
			int afterForced = calls.get();
			assertTrue("The first toggle must still refresh", afterForced > afterStart);

			// A second toggle inside the interval falls back to the caches it just wrote.
			wiki.refreshSetting();
			Thread.sleep(300);
			assertEquals("A repeated toggle must not download again", afterForced, calls.get());
		}
		finally { wiki.stop(); }
	}

	@Test
	public void onlyASourceTheWikiListsWithholdsTheLocalFallback() throws Exception
	{
		WikiRarity wiki = create();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(this::response).build();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		// The local dataset files both items under a source name the wiki tables never mention.
		wiki.dropRates.reload(java.util.Map.of("Boss variant",
			java.util.Map.of("Example", 0.002, "Unlisted", 0.004)));
		try
		{
			wiki.start();
			awaitCache(wiki);
			assertEquals("1/512", wiki.dropRateText("Boss", "Example"));
			// The wiki lists "Boss" and does not give it this item, so that absence is authoritative.
			assertNull("A listed source must not borrow a rate by name", wiki.dropRateText("Boss", "Unlisted"));
			// "Other boss" appears nowhere in the tables, so they say nothing and local data stands.
			assertEquals("1/500", wiki.dropRateText("Other boss", "Example"));
		}
		finally { wiki.stop(); }
	}

	@Test
	public void refreshUpdatesCompletionAndDropsEvenWhenBothCachesAreFresh() throws Exception
	{
		WikiRarity wiki = create();
		java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
		java.util.concurrent.atomic.AtomicBoolean updated = new java.util.concurrent.atomic.AtomicBoolean();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain -> {
			calls.incrementAndGet();
			if (updated.get() && chain.request().url().encodedPath().equals("/api.php"))
			{
				return WikiDropRatesTest.response(chain.request(), bucket(chain.request(), WikiDropRatesTest.row("Boss", "Example", "1/256")));
			}
			if (updated.get() && chain.request().url().encodedPath().endsWith("completion.json"))
			{
				return WikiDropRatesTest.response(chain.request(), "{\"1\":25}");
			}
			return response(chain);
		}).build();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		try
		{
			wiki.start();
			awaitCache(wiki);
			assertEquals("1/512", wiki.dropRateText("Boss", "Example"));
			assertEquals(Double.valueOf(50), wiki.entry(1, "Example").completion);
			// Two item/completion files plus the drop pages: one with rows, one empty to end the loop.
			assertEquals(4, calls.get());
			updated.set(true);
			wiki.refreshSetting();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (!"1/256".equals(wiki.dropRateText("Boss", "Example")) && System.nanoTime() < deadline) { Thread.sleep(10); }
			assertEquals("Explicit refresh must bypass both weekly caches", 8, calls.get());
			assertEquals("1/256", wiki.dropRateText("Boss", "Example"));
			assertEquals(Double.valueOf(25), wiki.entry(1, "Example").completion);
		}
		finally { wiki.stop(); }
	}

	@Test
	public void freshCachesWorkAfterRestartWithoutAnyNetworkRequests() throws Exception
	{
		WikiRarity first = create();
		first.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(this::response).build();
		when(first.config.refreshWikiData()).thenReturn(true);
		try { first.start(); awaitCache(first); }
		finally { first.stop(); }
		WikiRarity second = create();
		second.dataDirectory = first.dataDirectory;
		java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
		second.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain -> {
			calls.incrementAndGet();
			throw new java.io.IOException("Offline");
		}).build();
		when(second.config.refreshWikiData()).thenReturn(true);
		try
		{
			second.start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (second.dropRateText("Boss", "Example") == null && System.nanoTime() < deadline) { Thread.sleep(10); }
			assertEquals("1/512", second.dropRateText("Boss", "Example"));
			assertEquals(Double.valueOf(50), second.entry(1, "Example").completion);
			assertEquals(0, calls.get());
		}
		finally { second.stop(); }
	}

	@Test
	public void downloadedDataStaysInUseWithRefreshingSwitchedOff() throws Exception
	{
		WikiRarity first = create();
		first.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(this::response).build();
		when(first.config.refreshWikiData()).thenReturn(true);
		try { first.start(); awaitCache(first); }
		finally { first.stop(); }
		// Even a cache from before the weekly cutoff is better than no data at all.
		java.nio.file.Path completion = path(first.dataDirectory).resolve("wiki-completion-cache.json");
		java.nio.file.Files.writeString(completion,
			java.nio.file.Files.readString(completion).replaceFirst("\"fetchedAt\":\\d+", "\"fetchedAt\":1"));
		assertTrue(java.nio.file.Files.readString(completion).contains("\"fetchedAt\":1,"));
		WikiRarity second = create();
		second.dataDirectory = first.dataDirectory;
		java.util.concurrent.atomic.AtomicInteger calls = new java.util.concurrent.atomic.AtomicInteger();
		second.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain -> {
			calls.incrementAndGet();
			throw new java.io.IOException("Offline");
		}).build();
		when(second.config.refreshWikiData()).thenReturn(false);
		try
		{
			second.start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while ((second.dropRateText("Boss", "Example") == null || second.entry(1, "Example") == null) && System.nanoTime() < deadline)
			{
				Thread.sleep(10);
			}
			assertEquals("1/512", second.dropRateText("Boss", "Example"));
			assertEquals(Double.valueOf(50), second.entry(1, "Example").completion);
			assertEquals(0, calls.get());
		}
		finally { second.stop(); }
	}

	@Test
	public void disablingDuringDropDownloadCancelsWithoutReplacingCachedRates() throws Exception
	{
		WikiRarity wiki = create();
		CountDownLatch entered = new CountDownLatch(1);
		AtomicReference<Thread> worker = new AtomicReference<>();
		AtomicReference<okhttp3.Call> request = new AtomicReference<>();
		java.util.concurrent.atomic.AtomicBoolean block = new java.util.concurrent.atomic.AtomicBoolean();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(chain -> {
			if (block.get() && chain.request().url().encodedPath().equals("/api.php"))
			{
				worker.set(Thread.currentThread());
				request.set(chain.call());
				entered.countDown();
				try { new CountDownLatch(1).await(5, TimeUnit.SECONDS); }
				catch (InterruptedException expected) { Thread.currentThread().interrupt(); }
				return WikiDropRatesTest.response(chain.request(), bucket(chain.request(), WikiDropRatesTest.row("Boss", "Example", "1/256")));
			}
			return response(chain);
		}).build();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		try
		{
			wiki.start();
			awaitCache(wiki);
			java.nio.file.Path cache = path(wiki.dataDirectory).resolve("wiki-drop-rates-cache.json");
			String original = java.nio.file.Files.readString(cache);
			block.set(true);
			wiki.refreshSetting();
			assertTrue(entered.await(5, TimeUnit.SECONDS));
			when(wiki.config.refreshWikiData()).thenReturn(false);
			wiki.refreshSetting();
			worker.get().join(3000);
			assertFalse(worker.get().isAlive());
			assertTrue(request.get().isCanceled());
			assertEquals("1/512", wiki.dropRateText("Boss", "Example"));
			assertEquals(original, java.nio.file.Files.readString(cache));
		}
		finally { wiki.stop(); }
	}

	@Test
	public void enablingLoadsDataWithoutPluginRestart() throws Exception
	{
		WikiRarity wiki = create();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder().addInterceptor(this::response).build();
		try
		{
			wiki.start();
			when(wiki.config.refreshWikiData()).thenReturn(true);
			wiki.refreshSetting();
			verify(wiki.resolver, timeout(2000).atLeastOnce()).reload(anyMap());
		}
		finally
		{
			wiki.stop();
		}
	}

	@Test
	public void disablingCancelsAndRejectsLateNetworkResult() throws Exception
	{
		WikiRarity wiki = create();
		CountDownLatch entered = new CountDownLatch(1);
		AtomicReference<Thread> worker = new AtomicReference<>();
		when(wiki.config.refreshWikiData()).thenReturn(true);
		AtomicReference<okhttp3.Call> request = new AtomicReference<>();
		wiki.remote.http = new okhttp3.OkHttpClient.Builder()
							   .addInterceptor(chain -> {
								   request.set(chain.call());
								   worker.set(Thread.currentThread());
								   entered.countDown();
								   try
								   {
									   new CountDownLatch(1).await(2, TimeUnit.SECONDS);
								   }
								   catch (InterruptedException expected)
								   {
									   Thread.currentThread().interrupt();
								   }
								   return response(chain);
							   })
							   .build();
		try
		{
			wiki.start();
			assertTrue(entered.await(2, TimeUnit.SECONDS));
			when(wiki.config.refreshWikiData()).thenReturn(false);
			wiki.refreshSetting();
			worker.get().join(2000);
			assertFalse(worker.get().isAlive());
			assertTrue(request.get().isCanceled());
			verify(wiki.resolver, never()).reload(anyMap());
			assertNull(wiki.entry(1, "Example"));
		}
		finally
		{
			wiki.stop();
		}
	}
}

