			assertEquals(basis == RarityBasis.RARITY ? RarityTier.COMMON : RarityTier.VERY_RARE, result.getTier());
			assertNull(result.getCompPercent());
		}
	}
	@Test
	public void linkedGroundItemThresholdsUpdateWithoutCopyingSettings()
	{
