	{
		doNothing().when(sounds).playNow(anyString(), anyInt());
		when(sounds.gate.blocked()).thenReturn(true);
		for (int i = 0; i < 1000; i++) { sounds.offerValue("sound" + i + ".wav", 50, "Coins", -1, 0); }
