		int count = 0;
		for (int y = 0; y < 234; y++)
		{
			for (int x = 0; x < 480; x++)
			{
				count += images[0].getRGB(x, y) != images[1].getRGB(x, y) ? 1 : 0;
			}
		}
		return count;
	}

